SELECT id, service, level, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, COALESCE(context['trace'], 'unknown') AS trace_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs WHERE level IN ('ERROR', 'WARN');
